// snippets.ts: rendered with the goldens' own inputs, every client config equals the CLI's golden
// (examples/clients, generated by deedglass mcp snippet), byte for byte.
import { describe, expect, it } from 'vitest';
import { CLIENTS, GOLDEN, snippet } from '../src/lib/snippets.ts';
import { read, repo } from './helpers.ts';

const file: Record<string, string> = { 'claude-code': 'http-claude-code.sh', cursor: 'http-cursor.json', 'claude-desktop': 'http-claude-desktop.json' };

describe('snippets', () => {
  it.each(CLIENTS)('%s equals the CLI golden', (c) => {
    const text = snippet(c, { server: GOLDEN.server, apiKey: GOLDEN.apiKey, connector: GOLDEN.connector, command: GOLDEN.command }).text;
    expect(text).toBe(read(repo(`testdata/mcp/snippets/${file[c]}`)));
    expect(text).toBe(read(repo(`examples/clients/${file[c]}`)));
  });
  it('fills the server and key, and refuses values that would break the config', () => {
    const t = snippet('cursor', { server: 'http://127.0.0.1:18241', apiKey: 'dg_test_AAAAAAAA_bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb' }).text;
    expect(t).toContain('"url": "http://127.0.0.1:18241/mcp/native"');
    expect(t).toContain('Bearer dg_test_AAAAAAAA_bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb');
    const evil = snippet('claude-code', { server: "http://x' ; rm -rf ~", apiKey: '"}' }).text;
    expect(evil).not.toContain('rm -rf');
    expect(evil).toContain(GOLDEN.apiKey);
    expect(JSON.parse(snippet('claude-desktop', { server: 'http://127.0.0.1:18241', apiKey: 'k' }).text).mcpServers.deedglass.command).toBe('deedglass');
  });
});
